// 沿原正式48独有active坏档续接同代修复库；不重演任职成军，不改Installed内容或银行。
#define NAVAL_REPAIR_PROBE_LIBRARY
#include "naval_repair_world_probe.cpp"
namespace {
Bytes original_bank(const fs::path& path){std::ifstream input(path,std::ios::binary);check(bool(input),"original bank exists");return Bytes{std::istreambuf_iterator<char>(input),{}};}
}
// 参数只读原目录/失败银行/原formed对照；direct分支只测材料与事务，绝不冒原Plan红已修。
int main(int argc,char** argv){fs::path out;A trace;std::unique_ptr<ResidentReplaySession> session;try{
 check(argc==5||(argc==6&&std::string(argv[5])=="direct"),"catalog original-active-bank original-formed-bank fresh-output [direct]");const bool direct=argc==6;out=argv[4];check(!fs::exists(out),"fresh resumed repair evidence");fs::create_directories(out);const auto catalog=read(argv[1]);const auto active_input=original_bank(argv[2]),formed=original_bank(argv[3]);session=create_resident_replay_session();take(session->initialize_checkpoint(catalog,active_input),"original active bank formal cold admission");check(active_input==take(session->checkpoint(),"active original bytes"),"cold admission preserves exact original active bank bytes");
 auto before=repair_bundle(catalog,formed);auto active=cold_bank(*session,catalog,out,"active-cold-restored");auto working=repair_bundle(catalog,active);check(working.naval_repairs_enabled(),"actual original repair profile");check(working.naval.repairs.starts.size()==1&&working.naval.repairs.results.empty(),"original failed work is still active");const auto first=working.naval.repairs.starts.back();const auto ship=first.terms.vessel_id,inventory=first.terms.inventory_id;check(vessel(before,ship).integrity==20&&vessel(working,ship).integrity==20,"original explicit author damage and unfinished hull preserved");
 V intent=boundary::obj({{"request_key",V{first.request_key}},{"fleet_id",V{first.terms.fleet_id}},{"vessel_id",V{ship}},{"rule_id",V{first.terms.rule_id}},{"inventory_id",V{inventory}}});for(const auto& material:first.terms.materials)check(item_quantity(working.common,inventory,material.first,ReservationRef{first.id})==material.second&&item_quantity(working.common,inventory,material.first)==item_quantity(before.common,inventory,material.first),"exact original material reservation and quantity preserved");check(compare_boundary(personnel_and_money(before),personnel_and_money(working)).exact(),"original work preserves money and soldiers");
 success(*session,"naval_repair_start",intent,trace);cold_bank(*session,catalog,out,"early-replay");if(direct)success(*session,"advance",empty(),trace);else begin_repair_continue(*session,catalog,first.id,"resumed-repair-cancel-run",trace);cold_bank(*session,catalog,out,direct?"active-halfday":"active-plan");V cancel=boundary::obj({{"request_key",V{"resumed-risk-cancel"}},{"action_id",V{first.id}}});auto pre_cancel=take(session->checkpoint(),"before real resumed cancel");inject_apply=true;observed_apply=false;auto denied=command(*session,"naval_repair_cancel",cancel,trace);check(!ok(denied)&&observed_apply&&!inject_apply&&pre_cancel==take(session->checkpoint(),"cancel rollback"),"player late cancel failure restores exact full World");
 auto npc=repair_bundle(catalog,pre_cancel);const auto npc_before=take(encode_world_checkpoint(npc),"original NPC cancel state");auto typed=take(naval_repair_codec::decode_command("naval_repair_cancel",cancel),"actual typed cancellation");bool applied=true;inject_apply=true;observed_apply=false;take(try_npc_command(npc,player,CommandPayload{"naval_repair_cancel",typed},applied),"original NPC cancellation savepoint");check(!applied&&observed_apply&&!inject_apply&&npc_before==take(encode_world_checkpoint(npc),"NPC cancel rollback"),"NPC late actual cancellation preserves complete World");
 success(*session,"naval_repair_cancel",cancel,trace);auto cancelled=cold_bank(*session,catalog,out,"cancelled");auto released=repair_bundle(catalog,cancelled);check(!released.common.action(first.id)&&vessel(released,ship).integrity==20,"real cancellation releases crew without healing");if(!direct)check(released.player_plan.current&&released.player_plan.current->steps.back().phase==PlayerPlanStepPhase::blocked&&released.player_plan.current->steps.back().stop_reason=="NavalRepairCancelled","real zero-time cancellation closes original Continue with exact failure");for(const auto& material:first.terms.materials)check(item_quantity(released.common,inventory,material.first)==item_quantity(before.common,inventory,material.first)&&item_quantity(released.common,inventory,material.first,ReservationRef{first.id})==0,"cancel releases original finite materials");
 if(!direct)success(*session,"player_plan_clear",empty(),trace);auto complete_intent=intent;*complete_intent.find("request_key")=V{"resumed-risk-complete"};success(*session,"naval_repair_start",complete_intent,trace);auto current=repair_bundle(catalog,take(session->checkpoint(),"second real work"));if(direct)success(*session,"advance",empty(),trace);else begin_repair_continue(*session,catalog,current.naval.repairs.starts.back().id,"resumed-repair-complete-run",trace);const auto partial=cold_bank(*session,catalog,out,"partial");inject_finish=true;observed_finish=false;auto late=command(*session,"advance",empty(),trace);check(!ok(late)&&observed_finish&&!inject_finish,"real completion failure occurs after hull and materials writes");check(partial==take(session->checkpoint(),"completion rollback"),"whole World completion rollback exact");
 success(*session,"advance",empty(),trace);const auto completed=cold_bank(*session,catalog,out,"completed");auto finished=repair_bundle(catalog,completed);const auto actual=finished.naval.repairs.starts.back();check(vessel(finished,ship).integrity==40&&!finished.common.action(actual.id)&&finished.naval.repairs.results.back().success,"two actual work half-days repair original hull once");if(!direct)check(finished.player_plan.current&&finished.player_plan.current->steps.back().phase==PlayerPlanStepPhase::completed&&finished.player_plan.current->steps.back().stop_reason=="NavalRepairCompleted","actual Continue binds original successful result");for(const auto& material:actual.terms.materials)check(item_quantity(finished.common,inventory,material.first)==item_quantity(before.common,inventory,material.first)-material.second,"real completion consumes exact original recipe");const ArmyRecord* original_army=nullptr;for(const auto& army:before.military.armies)if(army.id==first.terms.army_id)original_army=&army;check(original_army&&before.common.wallet(original_army->wallet_id)&&finished.common.wallet(original_army->wallet_id)&&before.common.wallet(original_army->wallet_id)->balance==finished.common.wallet(original_army->wallet_id)->balance,"original repairing army wallet unchanged by free repair");for(const auto& id:original_army->unit_ids){const MilitaryUnitRecord* previous=nullptr;const MilitaryUnitRecord* after=nullptr;for(const auto& unit:before.military.military_units)if(unit.id==id)previous=&unit;for(const auto& unit:finished.military.military_units)if(unit.id==id)after=&unit;check(previous&&after&&previous->member_ids==after->member_ids,"repair creates no army personnel");}success(*session,"naval_repair_start",complete_intent,trace);cold_bank(*session,catalog,out,"completed-replay");
 auto broken=repair_bundle(catalog,completed);broken.naval.repairs.results.back().actor_id="qingxi::actor.south_officer";check(!broken.validate().ok,"full World rejects foreign repair result actor");write(out/"commands.json",V{trace});write(out/"result.json",boundary::obj({{"ok",V{true}},{"checks",V{Integer{checks}}},{"scope",V{direct?"ORIGINAL_NAVAL3_DIRECT_ASSET_COLD_TRANSACTION_ONLY":"ORIGINAL_NAVAL3_ACTIVE_BANK_RESUME_RISK_ONLY"}}}));std::cout<<"NAVAL_REPAIR_RESUME="<<checks<<" FAILURES=0\n";return 0;
 }catch(const std::exception& error){if(!out.empty()&&fs::exists(out)){write(out/"commands.json",V{trace});write(out/"failure.json",boundary::obj({{"checks",V{Integer{checks}}},{"error",V{StableId(error.what())}}}));if(session){auto bank=session->checkpoint();if(bank.ok)write(out/"failure.hmcb",bank.value);}}std::cerr<<"NAVAL_REPAIR_RESUME_FAIL checks="<<checks<<" "<<error.what()<<'\n';return 1;}}
